CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','user') NOT NULL DEFAULT 'user',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE items(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,category VARCHAR(60) NOT NULL,price_per_day INT UNSIGNED NOT NULL,stock INT UNSIGNED NOT NULL);
CREATE TABLE rentals(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,item_id INT NOT NULL,qty INT UNSIGNED NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,total INT UNSIGNED NOT NULL,status ENUM('active','returned') DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(item_id) REFERENCES items(id));
CREATE TABLE login_attempts(id INT AUTO_INCREMENT PRIMARY KEY,ip VARCHAR(45) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(ip,created_at));
CREATE TABLE activity_logs(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,action VARCHAR(255) NOT NULL,ip VARCHAR(45),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
